export function getFloorLaunchErrorMessage(code: FloorLaunchError): string {
  if (process.env['NODE_ENV'] !== 'production') {
    return (floorLaunchErrorMessages as Record<FloorLaunchError, string>)[code];
  }

  return 'Error message not available in production bundles.';
}

export function isFloorLaunchError<TProgramErrorCode extends FloorLaunchError>(
    error: unknown,
    transactionMessage: { instructions: Record<number, { programAddress: Address }> },
    code?: TProgramErrorCode,
): error is SolanaError<typeof SOLANA_ERROR__INSTRUCTION_ERROR__CUSTOM> & Readonly<{ context: Readonly<{ code: TProgramErrorCode }> }> {
  return isProgramError<TProgramErrorCode>(error, transactionMessage, FLOOR_LAUNCH_PROGRAM_ADDRESS, code);
}